/*
 * 03-index-records.js - the reveal observer and the lean-index record expansion.
 *
 * A partial of assets/js/site.js, which is generated by scripts/build-bundles.js
 * and must not be edited directly. Edit this file, then run that script.
 *
 * Concatenated rather than loaded as separate scripts because these share one
 * top-level scope: allProjects, langColors, currentPage and the rest are declared
 * in one partial and used in others. Splitting them into separate <script> tags
 * would change when each binding is initialised, and the boot calls at the end of
 * 07-extras must still run last.
 */
        // Reveal animation
        const revealElements = document.querySelectorAll('.reveal');
        const revealObserver = new IntersectionObserver((entries) => {
            entries.forEach(entry => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('visible');
                }
            });
        }, { threshold: 0.1, rootMargin: '0px 0px -50px 0px' });

        revealElements.forEach(el => revealObserver.observe(el));

        // Escape HTML to prevent XSS from user-controlled data
        function escapeHtml(text) {
            if (!text) return '';
            const div = document.createElement('div');
            div.textContent = text;
            return div.innerHTML;
        }

        // Lean index records use short keys to keep the file small. This restores the
        // field names the renderers use. The decoder itself lives in
        // assets/js/index-record.js, because the graph pages need it too and do
        // not load this bundle; keeping a second copy here is how the two would
        // drift.
        function expandIndexRecord(r) {
            return window.IndexRecord.expand(r);
        }
